// State Persistence
function initState() {
  // Load properties
  const savedProperties = localStorage.getItem("mialqui_properties");
  if (savedProperties) {
    properties = JSON.parse(savedProperties);

    // Auto-migrate old categories/schema if cached in browser LocalStorage
    let needsUpdate = false;
    properties.forEach(p => {
      if (p.category === "Cabañas" || p.category === "Quintas") {
        p.category = "Casas";
        needsUpdate = true;
      }
      if (!p.phone) {
        p.phone = ADMIN_WHATSAPP;
        needsUpdate = true;
      }
      if (!p.type) {
        p.type = "alquiler";
        needsUpdate = true;
      }
    });
    if (needsUpdate) {
      localStorage.setItem("mialqui_properties", JSON.stringify(properties));
    }
  } else {
    // If none, load from mockData.js
    properties = INITIAL_PROPERTIES;
    localStorage.setItem("mialqui_properties", JSON.stringify(properties));
  }

  // Load favorites
  const savedFavorites = localStorage.getItem("mialqui_favorites");
  if (savedFavorites) {
    favorites = JSON.parse(savedFavorites);
  } else {
    favorites = [];
  }

  // Load session
  isAdmin = sessionStorage.getItem("mialqui_admin") === "true";

  // Set initial price filter bound based on rentals
  maxPrice = 5000000;
}

