      category,
      price,
      phone,
      location,
      lat,
      lng,
      rating: 5.0, // Default rating for new properties
      reviewsCount: 0,
      description,
      images,
      amenities
    };
    properties.push(newProp);
    alert("Nueva propiedad agregada con éxito.");
  }

  // Reset form
  resetPropertyForm();

  // Persist State
  savePropertiesState();

  // Return to table list
  switchAdminView("list");
}

